sql.overridePlan.deletePlan:
DELETE
  FROM brs.override_plan_assigned_user
  WHERE override_plan_id = :planId;

DELETE
  FROM brs.override_plan_receiving_user
  WHERE override_plan_id = :planId;

 DELETE
  FROM brs.override_plan
   WHERE id = :planId;

sql.overridePlan.listAll:
SELECT array_to_json(array_agg(row_to_json(t))) FROM ( SELECT op.id, op.name, op.description, op.position_id as "positionId", op.total, ops.status_type AS status, count(au.*) FILTER (WHERE au.start_date <= now() AND (end_date IS NULL OR au.end_date > now())) as "activeAssignedUsers", coalesce(( SELECT array_to_json(array_agg(row_to_json(u))) FROM ( SELECT opu.user_id as "userId", concat(u.first_name, ' ', u.last_name) AS name, p.position, p.id AS "positionId", (select cfv.text_value from flow.user_custom_field_value cfv inner join flow.custom_field_group_assignment cfga on cfv.custom_field_group_assignment_id = cfga.id where cfga.custom_field_id in (9902,9400,3287,3286,3285,3284,3283,3282,3281,3280,3279,3278,3277,3276,3275,454,404) and cfga.archived is false and cfv.user_id = opu.user_id ) as "employeeId" FROM brs.override_plan_receiving_user opu INNER JOIN flow."user" u ON opu.user_id = u.id INNER JOIN flow.user_position up ON u.id = up.user_id INNER JOIN flow.position p ON up.position_id = p.id WHERE override_plan_id = op.id AND up.archived IS NOT TRUE AND up.primary_flag IS TRUE ) u), '[]') AS "receivingUsers", coalesce(( SELECT array_to_json(array_agg(row_to_json(u))) FROM ( SELECT opa.id, opa.user_id as "userId", concat(u.first_name, ' ', u.last_name) AS name, p.position, p.id AS "positionId", opa.start_date AS "startDate", opa.end_date AS "endDate", (select cfv.text_value from flow.user_custom_field_value cfv inner join flow.custom_field_group_assignment cfga on cfv.custom_field_group_assignment_id = cfga.id where cfga.custom_field_id in (9902,9400,3287,3286,3285,3284,3283,3282,3281,3280,3279,3278,3277,3276,3275,454,404) and cfga.archived is false and cfv.user_id = opa.user_id ) as "employeeId" FROM brs.override_plan_assigned_user opa INNER JOIN flow."user" u ON opa.user_id = u.id INNER JOIN flow.user_position up ON u.id = up.user_id INNER JOIN flow.position p ON up.position_id = p.id WHERE opa.override_plan_id = op.id AND up.archived IS NOT TRUE AND up.primary_flag IS TRUE
) u ), '[]') AS "assignedUsers"
FROM brs.override_plan op INNER JOIN brs.override_plan_status ops ON op.status_id = ops.id LEFT JOIN brs.override_plan_assigned_user au ON op.id = au.override_plan_id where case when :excludeInactive is true then op.status_id != 3 else 1=1 end and op.position_id = :positionId GROUP BY op.id, op.name, op.description, op.total, ops.status_type ORDER BY op.name ) t
